// Package sqlite is the SQLite adapter (ADR 0004). It opens the database through the pure Go
// driver modernc.org/sqlite with a single-connection writer pool and a reader pool, applies
// the embedded goose migrations and implements the persistence ports of internal/app.
//
// Queries are generated by sqlc into the sqlcgen package from queries/*.sql, with the
// migrations as schema. Regenerate them with the pinned sqlc version documented in
// sqlc.yaml; never edit sqlcgen by hand.
package sqlite

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"log/slog"
	"runtime"

	// Registers the pure Go "sqlite" database/sql driver (no cgo, ADR 0004).
	_ "modernc.org/sqlite"
)

// driverName is the database/sql name modernc.org/sqlite registers.
const driverName = "sqlite"

// writerMaxOpenConnections is one: SQLite allows a single writer at a time, and queueing
// writes in database/sql is cheaper and more predictable than retrying SQLITE_BUSY.
const writerMaxOpenConnections = 1

// ErrNoPath is returned by Open when Options.Path is empty.
var ErrNoPath = errors.New("no database path")

// Options configures Open.
type Options struct {
	// Path is the database file. The caller decides name and directory (ADR 0004:
	// <data>/server.db); the directory must exist. A missing file is created.
	Path string
	// Logger receives the adapter's own log records, e.g. ping failures and applied
	// migrations. Nil discards them.
	Logger *slog.Logger
}

// DB is an open SQLite database with a writer pool for statements that change data and a
// reader pool for queries. It is safe for concurrent use.
type DB struct {
	writer *sql.DB
	reader *sql.DB
	logger *slog.Logger
}

// Open opens or creates the database at options.Path and checks both pools with a ping, so
// a wrong path or locked file is reported here and not on the first query. The writer is
// opened first: it creates the file and switches it to WAL before any reader connects.
func Open(ctx context.Context, options Options) (*DB, error) {
	if options.Path == "" {
		return nil, ErrNoPath
	}

	writer, err := openPool(ctx, options.Path, writerRole)
	if err != nil {
		return nil, fmt.Errorf("open database writer: %w", err)
	}

	reader, err := openPool(ctx, options.Path, readerRole)
	if err != nil {
		return nil, errors.Join(fmt.Errorf("open database reader: %w", err), closePool("writer", writer))
	}

	return &DB{writer: writer, reader: reader, logger: loggerOrDiscard(options.Logger)}, nil
}

// Close closes both pools. It returns the errors of both, joined.
func (db *DB) Close() error {
	return errors.Join(closePool("reader", db.reader), closePool("writer", db.writer))
}

func openPool(ctx context.Context, databasePath string, role poolRole) (*sql.DB, error) {
	dataSource, err := dataSourceName(databasePath, role)
	if err != nil {
		return nil, err
	}

	pool, err := sql.Open(driverName, dataSource)
	if err != nil {
		return nil, fmt.Errorf("open %s: %w", databasePath, err)
	}

	pool.SetMaxOpenConns(maxOpenConnections(role))

	err = pool.PingContext(ctx)
	if err != nil {
		return nil, errors.Join(fmt.Errorf("connect to %s: %w", databasePath, err), pool.Close())
	}

	return pool, nil
}

func maxOpenConnections(role poolRole) int {
	if role == writerRole {
		return writerMaxOpenConnections
	}

	// Readers do not block each other in WAL mode; one per CPU keeps parallel queries busy
	// without piling up idle connections.
	return runtime.NumCPU()
}

func closePool(name string, pool *sql.DB) error {
	err := pool.Close()
	if err != nil {
		return fmt.Errorf("close database %s: %w", name, err)
	}

	return nil
}

func loggerOrDiscard(logger *slog.Logger) *slog.Logger {
	if logger == nil {
		return slog.New(slog.DiscardHandler)
	}

	return logger
}
